import Banner from "./Bannner"
import { useState,useRef,useEffect } from "react";
import HtmlRenderer from "./HtmlRenderer";
import { createClient } from "@supabase/supabase-js";
import ContactFooter from "./ContactFooter";
import glv from '../utils/getLocalizedValue';

const supabase = createClient(
  process.env.REACT_APP_SUPABASE_URL,
  process.env.REACT_APP_SUPABASE_ANON_KEY
);

function Openings() {
    const [careers, setCareers] = useState([]);
  
    useEffect(() => {
      getCareers();
    }, []);

    async function getCareers() {
      const { data, error } = await supabase
        .from("career")
        .select("*")
        .order("date", { ascending: false }); 
        
  
      if (error) {
        // console.error("Error fetching careers:", error);
      } else {
        setCareers(data);
      }
    }

  // date를 Due: YYYY/MM(ENG)/DD 형식으로 변환
  // 함수 아니고 변수
  // 예시 Due: 2025/JAN/16
  const dueDateString = (date) => {
    if (!date) return "ㅤ";
    const options = { year: 'numeric', month: 'short', day: '2-digit' };
    const formattedDate = new Date(date).toLocaleDateString('en-US', options);
    const [month, day, year] = formattedDate.replace(',', '').split(' ');
    return `Due: ${year}/${month.toUpperCase()}/${day}`;
  }

  return (
    <>
      {
        careers.map((career) => (
          glv(
            <OpeningContainer
              key={career.id}
              domain={career.domain}
              jobtitle={career.title}
              date={dueDateString(career.date) ?? "ㅤ"}
              content={<HtmlRenderer htmlString={career.html} className="prose tracking-[-0.015em]"/>}
            />,
            <OpeningContainer
              key={career.id}
              domain={career.domain}
              jobtitle={career.title_korean}
              date={dueDateString(career.date) ?? "ㅤ"}
              content={<HtmlRenderer htmlString={career.html_korean} className="prose tracking-[-0.015em]" />}
            />
          )
        ))
      }
    </>
  );
}

function OpeningContainer({ domain, jobtitle, content, date }) {
  let contentRef = useRef(null);
  let [isOpen, setIsOpen] = useState(false);
  return (
    <>
      <article className="sm:max-w-[70rem] w-full px-5 font-pretendard">
        <div className="shadow-lg w-full p-3 sm:p-10 items-center bg-brand-silicon-white mt-10">
          <div className="flex w-full h-[8rem] items-center justify-center">
            <div
              className={
                isOpen
                  ? "hidden"
                  : "mobile-hide flex sm:me-10 me-5 h-full items-center font-[400] sm:text-3xl text-2xl sm:pe-10 pe-5 sm:w-[15rem] w-[10rem] justify-center border-r-[1px] border-black"
              }
            >
              {domain && domain}
            </div>
            <div className="flex flex-col w-full h-full justify-end">
              <div className={!isOpen ? "hidden" : "sm:text-3xl text-2xl mb-5"}>
                {domain && domain}
              </div>
              <div className="sm:text-3xl text-3xl font-[900]">
                {jobtitle && jobtitle}
              </div>
              <div
                className={
                  !isOpen ? "sm:text-base text-sm font-[700] mt-5" : "hidden"
                }
              >
                {date && date}
              </div>
            </div>
            <div className="flex w-[3rem]">
              <button
                onClick={() => {
                  setIsOpen(!isOpen);
                }}
                className={`flex transition-transform duration-500 transform 
                  ${isOpen ? "scale-y-[-1]" : ""}`}
              >
                <img
                  src={require("../assets/icon/expand.png")}
                  alt=""
                  className="w-[3rem] object-contain"
                />
              </button>
            </div>
          </div>
          <div
            ref={contentRef}
            style={{
              maxHeight: isOpen
                ? `${contentRef.current?.scrollHeight}px`
                : "0px",
            }}
            className={`transition-[max-height] duration-500 ease-in-out overflow-hidden sm:text-xl text-sm leading-8 ${
              isOpen? "mt-10" : ""
            }`}
          >
            {content && content}
          </div>
        </div>
      </article>
    </>
  );
}

